export const importMyGuestDataBodyShiftsItemLocationMax = 160;

export const importMyGuestDataBodyShiftsMax = 1000;

export const importMyGuestDataBodyCheckinsItemWorkerNameMax = 80;


export const importMyGuestDataBodyCheckinsItemLevelMax = 40;

export const importMyGuestDataBodyCheckinsItemSymptomsJsonItemMax = 80;

export const importMyGuestDataBodyCheckinsItemSymptomsJsonMax = 20;

export const importMyGuestDataBodyCheckinsMax = 1000;

export const importMyGuestDataBodySessionsItemWorkerNameMax = 80;

export const importMyGuestDataBodySessionsItemDateRegExp = new RegExp('^\\d{4}-\\d{2}-\\d{2}$');
export const importMyGuestDataBodySessionsItemSiteTypeMax = 200;

export const importMyGuestDataBodySessionsItemBreaksMax = 100;

export const importMyGuestDataBodySessionsItemWaterLogsItemCupsMin = 0;
export const importMyGuestDataBodySessionsItemWaterLogsItemCupsMax = 8;

export const importMyGuestDataBodySessionsItemWaterLogsMax = 200;

export const importMyGuestDataBodySessionsItemPlanHoursItemTimeMax = 5;

export const importMyGuestDataBodySessionsItemPlanHoursItemWbgtFMin = -50;
export const importMyGuestDataBodySessionsItemPlanHoursItemWbgtFMax = 200;

export const importMyGuestDataBodySessionsItemPlanHoursItemCategoryMin = 0;
export const importMyGuestDataBodySessionsItemPlanHoursItemCategoryMax = 5;

export const importMyGuestDataBodySessionsItemPlanHoursItemWorkMinutesMin = 0;
export const importMyGuestDataBodySessionsItemPlanHoursItemWorkMinutesMax = 60;

export const importMyGuestDataBodySessionsItemPlanHoursItemRestMinutesMin = 0;
export const importMyGuestDataBodySessionsItemPlanHoursItemRestMinutesMax = 60;

export const importMyGuestDataBodySessionsItemPlanHoursItemWaterCupsMin = 0;
export const importMyGuestDataBodySessionsItemPlanHoursItemWaterCupsMax = 6;

export const importMyGuestDataBodySessionsItemPlanHoursMax = 24;

export const importMyGuestDataBodySessionsItemRemindersShownItemMax = 160;

export const importMyGuestDataBodySessionsItemRemindersShownMax = 500;

export const importMyGuestDataBodySessionsMax = 1000;



export const ImportMyGuestDataBody = zod.object({
  "profile": zod.object({
  "name": zod.string().min(1).max(importMyGuestDataBodyProfileNameMax),
  "language": zod.enum(['en', 'es']),
  "mode": zod.string().min(1).max(importMyGuestDataBodyProfileModeMax).regex(importMyGuestDataBodyProfileModeRegExp).optional(),
  "usualIntensity": zod.enum(['easy', 'moderate', 'hard']),
  "newToHeat": zod.boolean(),
  "notificationsEnabled": zod.boolean()
}),
  "crew": zod.array(zod.object({
  "name": zod.string().min(1).max(importMyGuestDataBodyCrewItemNameMax),
  "intensity": zod.enum(['easy', 'moderate', 'hard']),
  "newToHeat": zod.boolean()
})).max(importMyGuestDataBodyCrewMax),
  "shifts": zod.array(zod.object({
  "date": zod.string().regex(importMyGuestDataBodyShiftsItemDateRegExp),
  "location": zod.string().min(1).max(importMyGuestDataBodyShiftsItemLocationMax),
  "planJson": zod.record(zod.string(), zod.unknown())
})).max(importMyGuestDataBodyShiftsMax),
  "checkins": zod.array(zod.object({
  "id": zod.string().uuid().optional(),
  "workerName": zod.string().min(1).max(importMyGuestDataBodyCheckinsItemWorkerNameMax),
  "time": zod.string().min(1),
  "level": zod.string().min(1).max(importMyGuestDataBodyCheckinsItemLevelMax),
  "symptomsJson": zod.array(zod.string().max(importMyGuestDataBodyCheckinsItemSymptomsJsonItemMax)).max(importMyGuestDataBodyCheckinsItemSymptomsJsonMax),
  "detailsJson": zod.record(zod.string(), zod.unknown()).optional()
})).max(importMyGuestDataBodyCheckinsMax),
  "sessions": zod.array(zod.object({
  "workerName": zod.string().min(1).max(importMyGuestDataBodySessionsItemWorkerNameMax),
  "date": zod.string().regex(importMyGuestDataBodySessionsItemDateRegExp),
  "startedAt": zod.string().nullable(),
  "endedAt": zod.string().nullable(),
  "siteType": zod.string().max(importMyGuestDataBodySessionsItemSiteTypeMax),
  "breaks": zod.array(zod.object({
  "start": zod.string(),
  "end": zod.string().nullable()
})).max(importMyGuestDataBodySessionsItemBreaksMax),
  "waterLogs": zod.array(zod.object({
  "time": zod.string(),
  "cups": zod.number().min(importMyGuestDataBodySessionsItemWaterLogsItemCupsMin).max(importMyGuestDataBodySessionsItemWaterLogsItemCupsMax)
})).max(importMyGuestDataBodySessionsItemWaterLogsMax),
  "planHours": zod.array(zod.object({
  "at": zod.number(),
  "time": zod.string().max(importMyGuestDataBodySessionsItemPlanHoursItemTimeMax),
  "wbgtF": zod.number().min(importMyGuestDataBodySessionsItemPlanHoursItemWbgtFMin).max(importMyGuestDataBodySessionsItemPlanHoursItemWbgtFMax),
  "category": zod.number().int().min(importMyGuestDataBodySessionsItemPlanHoursItemCategoryMin).max(importMyGuestDataBodySessionsItemPlanHoursItemCategoryMax),
  "workMinutes": zod.number().min(importMyGuestDataBodySessionsItemPlanHoursItemWorkMinutesMin).max(importMyGuestDataBodySessionsItemPlanHoursItemWorkMinutesMax),
  "restMinutes": zod.number().min(importMyGuestDataBodySessionsItemPlanHoursItemRestMinutesMin).max(importMyGuestDataBodySessionsItemPlanHoursItemRestMinutesMax),
  "waterCups": zod.number().min(importMyGuestDataBodySessionsItemPlanHoursItemWaterCupsMin).max(importMyGuestDataBodySessionsItemPlanHoursItemWaterCupsMax)
})).max(importMyGuestDataBodySessionsItemPlanHoursMax),
  "remindersShown": zod.array(zod.string().max(importMyGuestDataBodySessionsItemRemindersShownItemMax)).max(importMyGuestDataBodySessionsItemRemindersShownMax)
})).max(importMyGuestDataBodySessionsMax).optional()
})

export const ImportMyGuestDataResponse = zod.object({
  "imported": zod.boolean(),
  "reason": zod.string().nullable()
})


/**
 * @summary Delete the signed-in user's Sombra data and account
 */
export const DeleteMyAccountResponse = zod.object({
  "deleted": zod.boolean()
})


